UPDATE ai_cost_alert
SET occurrence_count = occurrence_count + 1,
    last_seen_at = #{lastSeenAt},
    severity = #{severity},
    message = #{message}
WHERE id = #{id}

sql.where:
created_at >= #{from} AND created_at < #{to}
 AND alert_type = #{alertType} 
 AND alert_level = #{alertLevel} 
 AND status = #{status} 
 AND target_type = #{targetType}

mapper.select:
SELECT * FROM ai_cost_alert

ORDER BY created_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE ai_cost_alert
SET status = 'ACKNOWLEDGED', acknowledged_at = #{at}, acknowledged_by = #{by}
WHERE id = #{id} AND status = 'OPEN'

UPDATE ai_cost_alert
SET status = 'RESOLVED', resolved_at = #{at}
WHERE id = #{id} AND status <> 'RESOLVED'

mapper.select:
SELECT COUNT(*) FROM ai_cost_alert
WHERE status = 'OPEN' AND alert_level = #{level}
  AND (#{excludeType} IS NULL OR alert_type <> #{excludeType})

SELECT * FROM ai_cost_alert
WHERE alert_type = #{alertType}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND status IN ('OPEN', 'ACKNOWLEDGED')
ORDER BY threshold_value ASC, id ASC
